import{_ as t,o as a,c as o,ah as r}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Judicial Aftermath: Thomas Schmid (The Archivist of Power)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/gericht-thomas-schmid.md","filePath":"en/recherche/gericht-thomas-schmid.md"}'),i={name:"en/recherche/gericht-thomas-schmid.md"};function n(s,e,h,c,d,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="judicial-aftermath-thomas-schmid-the-archivist-of-power" tabindex="-1">Judicial Aftermath: Thomas Schmid (The Archivist of Power) <a class="header-anchor" href="#judicial-aftermath-thomas-schmid-the-archivist-of-power" aria-label="Permalink to &quot;Judicial Aftermath: Thomas Schmid (The Archivist of Power)&quot;">​</a></h1><p><strong>From loyal confidant to the most important crown witness of the Second Republic.</strong></p><p>Thomas Schmid was the man at the center of the &quot;Kurz System.&quot; As Secretary General in the Ministry of Finance and later CEO of ÖBAG, he managed not only state assets but also the informal networks of power. His secured chats are the &quot;Rosetta Stones&quot; of modern Austrian corruption research.</p><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>Thomas Schmid is the acoustic bridge in our project:</p><ul><li><strong>The Benko Axis:</strong> Schmid was René Benko&#39;s contact in the Ministry of Finance when it came to tax relief or COFAG aid.</li><li><strong>The Horten Donations:</strong> His chats provide the context for the &quot;aesthetic of splitting.&quot; He knew how to place donations to keep the system running without triggering an alarm.</li></ul><hr><h2 id="status-march-2026-the-showdown-in-linz" tabindex="-1">Status March 2026: The Showdown in Linz <a class="header-anchor" href="#status-march-2026-the-showdown-in-linz" aria-label="Permalink to &quot;Status March 2026: The Showdown in Linz&quot;">​</a></h2><p>Thomas Schmid is facing his most explosive appearance yet as a star witness in the trial against August Wöginger at the Linz Regional Court.</p><h3 id="_1-date-march-9-2026" tabindex="-1">1. Date: March 9, 2026 <a class="header-anchor" href="#_1-date-march-9-2026" aria-label="Permalink to &quot;1. Date: March 9, 2026&quot;">​</a></h3><p>Next Monday, Schmid will testify personally in Linz. He is the central witness for the prosecution (WKStA), as he directly implicates Wöginger as the &quot;inciter.&quot; He claims Wöginger incited him to intervene at the Braunau tax office.</p><h3 id="_2-defense-strategy-as-of-march-3-2026" tabindex="-1">2. Defense Strategy (as of March 3, 2026) <a class="header-anchor" href="#_2-defense-strategy-as-of-march-3-2026" aria-label="Permalink to &quot;2. Defense Strategy (as of March 3, 2026)&quot;">​</a></h3><p>Already on the first day of Wöginger&#39;s examination, the co-defendants (especially trade unionist Herbert B.) attacked Schmid frontally. His incriminating statements were described in the courtroom as a <strong>&quot;lie.&quot;</strong></p><ul><li><strong>The Goal:</strong> Schmid is to be discredited as untrustworthy before his appearance to jeopardize his crown witness status.</li><li><strong>Mockumentary Context:</strong> In Scene 13 (&quot;The Conductor of Proceedings&quot;), we use this dynamic. We portray Schmid as a tenor whose aria disturbs the harmony of power and who they therefore want to &quot;rhyme into silence.&quot;</li></ul><hr><p><em>Sources: Current trial reporting (March 3, 2026), interrogation protocols of the WKStA (2022-2024).</em></p>',17)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
